/** Язык интерфейса и компания «test» — в localStorage до загрузки страницы. */
export async function prepare(page: Page, lang: Lang) {
  await page.addInitScript(([l, company]) => {
    try {
      window.localStorage.setItem('preferred-language', l);
      window.localStorage.setItem('selected-company-id', company);
    } catch { /* ignore */ }
  }, [lang, TEST_COMPANY_ID] as const);
}

/** Страховка: запрос на отправку SMS обрывается и запоминается. В конце теста — expectNoSmsSent. */
export async function blockSmsSending(page: Page) {
  const hits: string[] = [];
  await page.route(/send-?sms/i, async (route) => {
    hits.push(route.request().url());
    await route.abort();
  });
  return hits;
}

export function expectNoSmsSent(hits: string[]) {
  expect(hits, 'тест не должен отправлять SMS').toEqual([]);
}

export async function openNewJob(page: Page, lang: Lang) {
  await page.goto('/JobForm?action=new');
  const tabs = page.getByRole('tablist').getByRole('tab');
  await expect(tabs).toHaveCount(2);
  await expect(tabs.first()).toHaveText(L[lang].jobInfoTab);
  await expect(tabs.first()).toHaveAttribute('aria-selected', 'true');
  return tabs;
}

/** Вкладка Dispatch — вторая (в HE её название пока не переведено, поэтому по позиции). */
export async function openDispatch(page: Page, lang: Lang): Promise<Locator> {
  const dispatchTab = page.getByRole('tablist').getByRole('tab').nth(1);
  await dispatchTab.click();
  await expect(dispatchTab).toHaveAttribute('aria-selected', 'true');
  const panel = page.getByRole('tabpanel');
  await expect(panel.getByRole('combobox', { name: L[lang].assign })).toBeVisible();
  await expect(panel.getByText(L[lang].preview, { exact: true })).toBeVisible();
  return panel;
}

/** Job Info: клиент, телефон, адрес (без выбора подсказки Google), тип, описание. Ничего не сохраняет. */
export async function fillJobInfo(page: Page) {
  const panel = page.getByRole('tabpanel');
  await panel.locator('#client_name').fill(JOB.client);
  await panel.locator('#phone').fill(JOB.phoneTyped);
  await panel.locator('#address-input').fill(JOB.address);
  await page.keyboard.press('Escape');
  await panel.locator('#job_type').click();
  await page.getByRole('option', { name: JOB.type, exact: true }).click();
  await expect(panel.locator('#job_type')).toHaveText(JOB.type);
  await panel.locator('#job_description').fill(JOB.note);
}

/** Блок превью SMS — <pre> с текстом, начинающимся с «Powered by Techory.AI». */
export const previewBlock = (panel: Locator) => panel.locator('pre').filter({ hasText: 'Powered by Techory.AI' });

export async function previewLines(panel: Locator): Promise<string[]> {
  const pre = previewBlock(panel);
  await expect(pre).toBeVisible();
  return (await pre.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
}

/** Выбрать техника в Assign Technician (вкладка Dispatch). */
export async function pickTechnician(page: Page, panel: Locator, lang: Lang, name: string) {
  const combo = panel.getByRole('combobox', { name: L[lang].assign });
  const option = page.getByRole('option', { name: new RegExp(`^${name}\\b`) });
  if (!(await option.isVisible())) await combo.click();
  await option.click();
  if (await page.getByRole('listbox').isVisible()) await page.keyboard.press('Escape');
}
